在sg2000的网卡驱动代码里 start_mac_and_dma() 之后加一段，只打这 5 个值：


uint32_t csr0 = getreg32(base + DMA_BUS_MODE);
uint32_t csr3 = getreg32(base + DMA_RCV_BASE_ADDR);
uint32_t csr4 = getreg32(base + DMA_TX_BASE_ADDR);
uint32_t csr5 = getreg32(base + DMA_STATUS);
uint32_t csr6 = getreg32(base + DMA_CONTROL);

syslog(LOG_ERR, "DIAG: CSR0=0x%08x CSR3=0x%08x CSR4=0x%08x "
                "CSR5=0x%08x CSR6=0x%08x\n",
                csr0, csr3, csr4, csr5, csr6);
syslog(LOG_ERR, "DIAG: TX_DESC0=0x%08x RX_DESC0=0x%08x\n",
                priv->tx_desc[0].des0, priv->rx_desc[0].des0);

